package com.nivor.file;import java.time.LocalDateTime;
public final class FileDtos{private FileDtos(){}public record FileView(Long id,String originalName,String mimeType,long size,String category,Long projectId,LocalDateTime createdAt){static FileView from(FileAsset x){return new FileView(x.getId(),x.getOriginalName(),x.getMimeType(),x.getSize(),x.getCategory(),x.getProject()==null?null:x.getProject().getId(),x.getCreatedAt());}}public record AnalysisView(Long id,AnalysisStatus status,String summary,LocalDateTime createdAt){static AnalysisView from(DocumentAnalysis x){return new AnalysisView(x.getId(),x.getStatus(),x.getSummary(),x.getCreatedAt());}}}
